package com.bank.txa.core;

import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.function.Function;
import java.util.function.Predicate;
import java.util.logging.Logger;

// A dataset that records transformations lazily and only runs them on an action.
public class LazyDataset<T> {
    private static final Logger log = Logger.getLogger(LazyDataset.class.getName());

    private final List<T> source;                       // base data
    private final List<Function<List<Object>, List<Object>>> plan; // recorded transformations
    private static int executionCounter = 0;            // proves actions re-run the plan

    public LazyDataset(List<T> source) {
        this.source = source;
        this.plan = new ArrayList<>();
    }

    private LazyDataset(List<T> source, List<Function<List<Object>, List<Object>>> plan) {
        this.source = source;
        this.plan = plan;
    }

    // TRANSFORMATION: lazy — records intent, returns a new dataset.
    public LazyDataset<T> filter(Predicate<T> p) {
        log.info(() -> "transformation filter() recorded (LAZY — nothing runs)");
        List<Function<List<Object>, List<Object>>> next = new ArrayList<>(plan);
        next.add(in -> {
            List<Object> out = new ArrayList<>();
            for (Object o : in) { @SuppressWarnings("unchecked") T t = (T) o; if (p.test(t)) out.add(o); }
            return out;
        });
        return new LazyDataset<>(source, next);
    }

    // TRANSFORMATION: lazy map.
    public <R> LazyDataset<R> map(Function<T, R> f) {
        log.info(() -> "transformation map() recorded (LAZY — nothing runs)");
        List<Function<List<Object>, List<Object>>> next = new ArrayList<>(plan);
        next.add(in -> {
            List<Object> out = new ArrayList<>();
            for (Object o : in) { @SuppressWarnings("unchecked") T t = (T) o; out.add(f.apply(t)); }
            return out;
        });
        return new LazyDataset<>(source, next);
    }

    // TRANSFORMATION: lazy distinct.
    public LazyDataset<T> distinct() {
        log.info(() -> "transformation distinct() recorded (LAZY — nothing runs)");
        List<Function<List<Object>, List<Object>>> next = new ArrayList<>(plan);
        next.add(in -> new ArrayList<>(new LinkedHashSet<>(in)));
        return new LazyDataset<>(source, next);
    }

    // Internal: run the recorded plan (called only by actions).
    private List<Object> execute() {
        executionCounter++;
        log.info(() -> "ACTION triggers execution #" + executionCounter
                + " of " + plan.size() + " recorded transformations");
        List<Object> data = new ArrayList<>(source);
        for (Function<List<Object>, List<Object>> step : plan) data = step.apply(data);
        return data;
    }

    // ACTION: count — triggers execution, returns a value.
    public long count() {
        return execute().size();
    }

    // ACTION: collect — triggers execution, returns the data to the Driver.
    @SuppressWarnings("unchecked")
    public List<T> collect() {
        return (List<T>) execute();
    }
}
