package com.bank.txa;

import com.bank.txa.core.LazyDataset;
import com.bank.txa.model.Txn;
import java.math.BigDecimal;
import java.util.List;
import java.util.logging.*;

public class TxaDemo {
    private static final Logger log = Logger.getLogger(TxaDemo.class.getName());

    static {
        Logger root = Logger.getLogger("");
        for (Handler h : root.getHandlers()) root.removeHandler(h);
        ConsoleHandler ch = new ConsoleHandler();
        ch.setLevel(Level.ALL);
        ch.setFormatter(new TxaLogFormatter());
        root.addHandler(ch);
        root.setLevel(Level.INFO);
    }

    public static void main(String[] args) {
        List<Txn> txns = List.of(
            new Txn("SAV2001", new BigDecimal("1000")),
            new Txn("CUR3001", new BigDecimal("500")),
            new Txn("SAV2001", new BigDecimal("3000"))
        );

        // Build a lazy chain of transformations — nothing executes here.
        LazyDataset<BigDecimal> rajeshAmounts = new LazyDataset<>(txns)
            .filter(t -> t.getAccountId().equals("SAV2001"))
            .map(Txn::getAmount);

        log.info("Chain built. No execution happened yet.");

        // First ACTION — triggers execution #1.
        long n = rajeshAmounts.count();
        log.info(() -> "count() = " + n);

        // Second ACTION on the same chain — triggers execution #2 (recomputes!).
        List<BigDecimal> amounts = rajeshAmounts.collect();
        log.info(() -> "collect() = " + amounts);
    }
}

